import os
import time
from typing import Any, Dict, List, Optional

import assemblyai as aai


def _normalize_items(items: Any) -> List[Dict[str, Any]]:
    normalized: List[Dict[str, Any]] = []
    if not items:
        return normalized

    for item in items:
        if isinstance(item, dict):
            normalized.append(item)
        else:
            normalized.append(
                {
                    "text": getattr(item, "text", None),
                    "start": getattr(item, "start", None),
                    "end": getattr(item, "end", None),
                    "speaker": getattr(item, "speaker", None),
                    "confidence": getattr(item, "confidence", None),
                }
            )
    return normalized


def _get_words_or_segments(transcript: Any) -> List[Dict[str, Any]]:
    word_attributes = getattr(transcript, "words", None)
    if word_attributes:
        return _normalize_items(word_attributes)

    utterances = getattr(transcript, "utterances", None)
    if utterances:
        return _normalize_items(utterances)

    segments = getattr(transcript, "segments", None)
    if segments:
        return _normalize_items(segments)

    return []


def transcribe_with_timestamps(
    audio_url: Optional[str] = None,
    audio_path: Optional[str] = None,
    poll_interval_seconds: float = 2.0,
    timeout_seconds: float = 3600.0,
) -> List[Dict[str, Any]]:
    api_key = os.environ.get("ASSEMBLYAI_API_KEY")
    if not api_key:
        raise ValueError("ASSEMBLYAI_API_KEY environment variable is required")

    aai.settings.api_key = api_key

    transcriber = aai.Transcriber()
    config = aai.TranscriptionConfig(
        punctuate=True,
        format_text=True,
        disfluencies=False,
        speaker_labels=True,
        auto_highlights=False,
    )

    if audio_url:
        transcript = transcriber.transcribe(audio_url, config=config)
    elif audio_path:
        transcript = transcriber.transcribe(audio_path, config=config)
    else:
        raise ValueError("Either audio_url or audio_path must be provided")

    start_time = time.time()
    while getattr(transcript, "status", None) not in ("completed", "error", "cancelled"):
        if time.time() - start_time > timeout_seconds:
            raise TimeoutError("Timed out waiting for transcription to complete")
        time.sleep(poll_interval_seconds)
        transcript = transcriber.get_transcript(getattr(transcript, "id", transcript))

    if getattr(transcript, "status", None) != "completed":
        raise RuntimeError(f"Transcription failed with status: {getattr(transcript, 'status', None)}")

    return _get_words_or_segments(transcript)
